#!/bin/zsh
# QuikCal release asset preparation (2026-11-08, Sparkle updates).
#
# Produces, from the ALREADY-BUILT build/QuikCal.app (run scripts/build_dmg.sh
# first — this script never rebuilds):
#   dist/release-v<version>/QuikCal-<version>.zip   Sparkle update enclosure
#   dist/release-v<version>/appcast.xml             EdDSA-signed appcast
#
# The EdDSA signature is generated by Sparkle's official `generate_appcast`
# from the private key in the LOGIN KEYCHAIN (never exported, never printed).
# The enclosure URL points at the immutable, version-specific GitHub release
# asset URL. This script does NOT publish anything — publishing is a separate
# explicit human action (scripts/publish_release.sh).
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

VERSION="$(/usr/libexec/PlistBuddy -c 'Print :CFBundleShortVersionString' "$ROOT/Resources/Info.plist")"
BUILD_NUM="$(/usr/libexec/PlistBuddy -c 'Print :CFBundleVersion' "$ROOT/Resources/Info.plist")"
APP="$ROOT/build/QuikCal.app"
SPARKLE_BIN="$ROOT/.build/artifacts/sparkle/Sparkle/bin"
OUT="$ROOT/dist/release-v${VERSION}"
ZIP="$OUT/QuikCal-${VERSION}.zip"
FEED_STABLE="https://github.com/bootsphotography1-beep/QuikCal/releases/latest/download/appcast.xml"
ENCLOSURE_PREFIX="https://github.com/bootsphotography1-beep/QuikCal/releases/download/v${VERSION}"

if [[ ! -d "$APP" ]]; then
  echo "Missing $APP — run scripts/build_dmg.sh first (this script never rebuilds)." >&2
  exit 1
fi
if [[ ! -x "$SPARKLE_BIN/generate_appcast" ]]; then
  echo "Missing Sparkle tools at $SPARKLE_BIN (swift package resolve)." >&2
  exit 1
fi

echo "==> Preparing release assets for QuikCal ${VERSION} (build ${BUILD_NUM})"
rm -rf "$OUT"
mkdir -p "$OUT"

echo "==> Zipping app (ditto — preserves symlinks + code signature)"
ditto -c -k --sequesterRsrc --keepParent "$APP" "$ZIP"

echo "==> Verifying the EXACT archive bytes: extract + codesign + version + hashes"
TMP="$(mktemp -d "${TMPDIR:-/tmp}/quikcal-release-verify-XXXXXX")"
trap 'rm -rf "$TMP"' EXIT
ditto -x -k "$ZIP" "$TMP"
codesign --verify --strict "$TMP/QuikCal.app"
ZIP_VER="$(/usr/libexec/PlistBuddy -c 'Print :CFBundleShortVersionString' "$TMP/QuikCal.app/Contents/Info.plist")"
ZIP_BUILD="$(/usr/libexec/PlistBuddy -c 'Print :CFBundleVersion' "$TMP/QuikCal.app/Contents/Info.plist")"
[[ "$ZIP_VER" = "$VERSION" && "$ZIP_BUILD" = "$BUILD_NUM" ]] \
  || { echo "Archive version mismatch: $ZIP_VER/$ZIP_BUILD" >&2; exit 1; }
codesign --verify --strict "$TMP/QuikCal.app/Contents/Frameworks/Sparkle.framework"
BUILT_EXE_SHA="$(shasum -a 256 "$APP/Contents/MacOS/QuietCalendar" | awk '{print $1}')"
ZIP_EXE_SHA="$(shasum -a 256 "$TMP/QuikCal.app/Contents/MacOS/QuietCalendar" | awk '{print $1}')"
[[ "$BUILT_EXE_SHA" = "$ZIP_EXE_SHA" ]] || { echo "Executable hash mismatch build vs zip" >&2; exit 1; }
echo "Archive verified: signed app ${ZIP_VER}, executable SHA-256 == build ($ZIP_EXE_SHA)"

echo "==> Release notes"
# Title interpolates the live version; the body heredoc stays single-quoted
# so its text is preserved verbatim.
cat > "$OUT/QuikCal-${VERSION}.md" <<TITLE
# QuikCal ${VERSION} — Spoken clock times ("three o'clock")

TITLE
cat >> "$OUT/QuikCal-${VERSION}.md" <<'NOTES'
- Spoken clock times now work: "Have a meeting on Tuesday at three o'clock" resolves straight to a Tuesday 3:00 pm draft for normal confirmation — previously it was wrongly rejected with "Please include a time".
- Supports common spoken forms: "three o'clock", "3 o'clock", "half past three", "quarter to four", "at three thirty", "three pm", and curly-apostrophe/oclock spellings.
- Sensible daytime inference (owner-approved): when you say a clock hour with no am/pm, QuikCal picks the unique time inside ordinary daytime meeting hours (9:00–17:00) — "three o'clock" means 3:00 pm, "ten o'clock" means 10:00 am, "twelve o'clock" means noon. The inferred time is labelled on the review card and fully editable.
- Your explicit wording always wins: "3am", "in the morning", "in the afternoon", "at night" (e.g. "eight at night" → 8:00 pm) override the heuristic.
- Genuinely ambiguous hours (six, seven, eight o'clock with no other context) still ask — now with tappable "7:00 am / 7:00 pm" chips instead of a dead-end message. Bare digit times ("3:00", "at 3") keep the same ask with chips too.
- Clock words are removed from the event title ("Have a meeting at three o'clock" → "Have a meeting"), and words that are NOT times are never treated as one: "remind me three hours before" stays a reminder, "meeting for three hours" stays a duration, and a named event like "Three Oclock Club" keeps its name.
- Everything else is unchanged: date handling, time zone, reminders, duration, locations, numeric/noon/midnight times, the Spotlight capture bar, Sparkle update checks, and Google Calendar OAuth.
NOTES

echo "==> Generating EdDSA-signed appcast (private key stays in login Keychain)"
"$SPARKLE_BIN/generate_appcast" \
  --download-url-prefix "$ENCLOSURE_PREFIX" \
  --embed-release-notes \
  "$OUT"
APPCAST="$OUT/appcast.xml"
[[ -f "$APPCAST" ]] || { echo "generate_appcast did not produce appcast.xml" >&2; exit 1; }

# generate_appcast's --download-url-prefix does not keep the version-tag
# path segment, so pin the enclosure URL deterministically to the immutable,
# version-specific GitHub release asset URL. This is safe: the EdDSA
# signature covers the ZIP bytes, not the appcast (SURequireSignedFeed is
# not enabled), and all other item metadata stays as generated.
ENCLOSURE_URL="${ENCLOSURE_PREFIX}/QuikCal-${VERSION}.zip"
/usr/bin/sed -i '' "s#url=\"[^\"]*QuikCal-${VERSION}.zip\"#url=\"${ENCLOSURE_URL}\"#" "$APPCAST"

echo "==> Essential appcast checks"
ZIP_LEN="$(stat -f%z "$ZIP")"
grep -q "sparkle:edSignature=" "$APPCAST" || { echo "appcast missing EdDSA signature" >&2; exit 1; }
grep -q "length=\"$ZIP_LEN\"" "$APPCAST" || { echo "appcast enclosure length != zip size ($ZIP_LEN)" >&2; exit 1; }
grep -q "url=\"${ENCLOSURE_PREFIX}/QuikCal-${VERSION}.zip\"" "$APPCAST" \
  || { echo "appcast enclosure URL is not the exact version-specific release asset URL" >&2; exit 1; }
grep -q "<sparkle:version>${BUILD_NUM}</sparkle:version>" "$APPCAST" \
  || { echo "appcast missing sparkle:version ${BUILD_NUM}" >&2; exit 1; }
grep -q "<sparkle:minimumSystemVersion>" "$APPCAST" \
  || { echo "appcast missing minimumSystemVersion" >&2; exit 1; }
echo "Enclosure: ${ENCLOSURE_PREFIX}/QuikCal-${VERSION}.zip"
echo "Feed (stable latest): $FEED_STABLE"

echo "==> Asset SHA-256"
shasum -a 256 "$ZIP" "$APPCAST"
echo "==> Sizes"
ls -lh "$OUT"
echo
echo "DONE — assets prepared in $OUT (NOT published; publish explicitly with scripts/publish_release.sh after review)."
